contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Single public test function. Parameters:
    // - senderAmount: the ether amount this test will send when calling c.Put; verifier will try 0 to expose mutant
    // - unlock: the unlockTime parameter forwarded to c.Put
    // Note: the test must hold for all inputs on original P and be violated by mutant M that requires msg.value>0
    function check(uint senderAmount, uint unlock) public {
        // ensure this contract has enough balance to send senderAmount
        require(address(this).balance >= senderAmount);

        // record pre-state balance of the account mapping via public getter Acc(address) => (unlockTime,balance)
        // Acc is public mapping of C, so c.Acc(address) returns (uint,uint) in that order per original contract
        (uint preUnlock, uint preBal) = c.Acc(address(this));

        // Call Put forwarding senderAmount wei. This is the single state-changing call on c.
        c.Put{value: senderAmount}(unlock);

        // observe post-state
        (uint postUnlock, uint postBal) = c.Acc(address(this));

        // The distinguishing property: calling Put with zero value must NOT revert on original contract
        // and must leave the numeric balance unchanged (since msg.value==0), but may update unlockTime to at least previous timestamp-derived value.
        // We express a single comparison that captures that when senderAmount == 0, the stored balance does not increase.
        assert(!(senderAmount == 0) || postBal == preBal);
    }

    // allow depositing ETH into this test contract so it can forward funds
    receive() external payable {}
}

