pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzz parameters: actor address and a candidate unlockTime and a deposit amount
    function testFuzz_property(address actor, uint256 unlockTime, uint256 amount) public {
        // keep actor non-zero
        vm.assume(actor != address(0));
        // bound amount to a reasonable range so we can fund the actor
        amount = bound(amount, 0, 10 ether);
        // fund actor so they can send value
        vm.deal(actor, amount);
        // perform Put as actor with provided unlockTime and amount
        vm.prank(actor);
        // call Put with value 'amount'
        c.Put{value: amount}(unlockTime);

        // Single assertion: for the reference contract, acc.unlockTime for actor is >= block.timestamp
        // This reads the public mapping Acc and its unlockTime via the autogenerated getter.
        (uint256 gotUnlockTime, uint256 gotBalance) = c.Acc(actor);
        // The invariant: recorded unlockTime is never in the past relative to current block timestamp
        assertTrue(gotUnlockTime >= block.timestamp);
    }
}

