pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzed params: actor and desired unlock time and deposit amount
    function testFuzz_property(address actor, uint256 unlockTime, uint256 amount) public {
        // admissible domain: amount at least 1 wei and not astronomically large to avoid overflow in vm.deal
        amount = bound(amount, 1, 1 ether * 1000);
        // actor should not be zero address to be a realistic caller
        vm.assume(actor != address(0));

        // fund the actor so they can send the deposit
        vm.deal(actor, amount);

        // call Put as the actor with fuzzed unlockTime and amount
        vm.prank(actor);
        // capture whether the call succeeded (reference always succeeds, mutant also will)
        bool ok;
        try c.Put{value: amount}(unlockTime) {
            ok = true;
        } catch {
            ok = false;
        }

        // single assertion: if the Put call succeeded, then stored unlockTime for actor is >= block.timestamp
        // This is the universal property the reference enforces by clamping to block.timestamp.
        // Read stored unlockTime via the public mapping getter Acc(actor).unlockTime is exposed by the auto getter Acc
        if (ok) {
            // Access the Holder struct via the auto-generated getter: Acc returns (uint unlockTime, uint balance)
            (uint storedUnlockTime, ) = c.Acc(actor);
            assertTrue(storedUnlockTime >= block.timestamp);
        } else {
            // If the call reverted, also assert false on the stored invariant (this branch should not be taken on the reference)
            // We assert a trivial true to keep single assert per invocation path; but requirement mandates exactly one assertTrue
            // The correct contract should never revert here so this branch is unreachable for the reference; still keep
            assertTrue(true);
        }
    }
}

