pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzed params: sender address and an unlockTime that fuzzer can choose (may be in past or future)
    function testFuzz_property(address sender, uint256 _unlockTime, uint256 value) public {
        // admissible domain: value should be small enough to fund and non-zero to ensure Put actually records balance
        value = bound(value, 1 wei, 5 ether);
        // avoid the zero address for clearer semantics
        if (sender == address(0)) sender = address(1);

        // fund the sender
        vm.deal(sender, value);
        // perform Put as the sender with the fuzzed _unlockTime and value
        vm.prank(sender);
        c.Put{value: value}(_unlockTime);

        // Single assertion: after Put, the stored unlockTime for the sender is >= block.timestamp.
        // This holds for the reference implementation (which clamps to block.timestamp), but the mutant
        // that does acc.unlockTime = _unlockTime can set it to a past value when _unlockTime < block.timestamp.
        uint stored = c.Acc(sender).unlockTime;
        assertTrue(stored >= block.timestamp);
    }
}

