pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // Fuzz parameters: actor address and _unlockTime value. We let the fuzzer pick both.
    // The property: calling Put cannot decrease the stored unlockTime for that msg.sender.
    function testFuzz_property(address actor, uint256 _unlockTime) public {
        vm.assume(actor != address(0));
        // ensure actor has some ETH to call Put (could be zero, but allow both). Give small amount so test wide.
        vm.deal(actor, 1 ether);

        // Step 1: actor sets an initial unlockTime (maybe large) so stored value may be high
        vm.startPrank(actor);
        // initial deposit with unlockTime = _unlockTime to set baseline
        c.Put{value: 0}(_unlockTime);
        uint256 before = c.Acc(actor).unlockTime;

        // Warp forward to ensure block.timestamp can change between calls
        vm.warp(block.timestamp + 1);

        // Step 2: actor calls Put again with any (fuzzed) _unlockTime and possibly zero value
        c.Put{value: 0}(_unlockTime);
        uint256 after = c.Acc(actor).unlockTime;
        vm.stopPrank();

        // Assert that unlockTime was not decreased by Put: after >= before
        // Reference implementation preserves this (it sets to max(_unlockTime, block.timestamp)); mutant assigning directly can make after < before.
        assertTrue(after >= before);
    }
}

