pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzing actor, amount, and a candidate unlock time
    function testFuzz_property(address actor, uint256 amount, uint256 candidateUnlock) public {
        // keep actor non-zero
        vm.assume(actor != address(0));
        // keep amount at least 1 wei and not absurdly large
        amount = bound(amount, 1, 1 ether * 1000);

        // We want to test the rule: when caller supplies _unlockTime > block.timestamp,
        // after Put the stored unlockTime >= supplied _unlockTime (i.e., preservation of a future unlock).
        // If candidateUnlock <= block.timestamp this rule is vacuous; to let fuzzer explore both
        // worlds we keep it wide and will only assert the rule when candidateUnlock > block.timestamp.

        // Fund the actor so they can send the amount
        vm.deal(actor, amount);
        // perform the Put from actor with the fuzzed candidateUnlock
        vm.prank(actor);
        c.Put{value: amount}(candidateUnlock);

        // Read stored holder for actor via public mapping getter Acc
        (uint storedUnlockTime, uint storedBalance) = c.Acc(actor);

        // If the caller supplied a future unlock (strictly greater than current block.timestamp at call time),
        // the correct contract ensures storedUnlockTime >= candidateUnlock. The mutant that sets unlockTime = block.timestamp
        // will violate this whenever candidateUnlock > block.timestamp. We must assert that property holds.
        if (candidateUnlock > block.timestamp) {
            // single assertion required
            assertTrue(storedUnlockTime >= candidateUnlock);
        } else {
            // when candidateUnlock <= block.timestamp the reference sets unlockTime to block.timestamp,
            // so storedUnlockTime >= block.timestamp holds; check that as well to keep the property general.
            assertTrue(storedUnlockTime >= block.timestamp);
        }
    }
}
